class Scoreboard
    private define homePoints as integer;
    private define awayPoints as integer;

    method constructor()
        this.homePoints <- 0;
        this.awayPoints <- 0;
    endMethod

    public method AddHome()
        this.homePoints <- this.homePoints + 1;
    endMethod

    public method AddAway()
        this.awayPoints <- this.awayPoints + 1;
    endMethod

    public method Difference() as integer
        return this.homePoints - this.awayPoints;
    endMethod
endClass

algorithm RunScoreboard
    define homeGoals as integer;
    define awayGoals as integer;
    define i as integer;
    define scoreboard as Scoreboard;
    read homeGoals;
    read awayGoals;
    scoreboard <- new Scoreboard();
    for i <- 1 to homeGoals step 1 do
        scoreboard.AddHome();
    endFor
    for i <- 1 to awayGoals step 1 do
        scoreboard.AddAway();
    endFor
    write scoreboard.Difference();
endAlgorithm
